75	/// The internal implementation of `layout_page_run`.
76	#[comemo::memoize]
77	#[expect(clippy::too_many_arguments)]
78	fn layout_page_run_impl(
79	    world: Tracked<dyn World + '_>,
80	    library: &LazyHash<Library>,
81	    introspector: Tracked<dyn Introspector + '_>,
82	    traced: Tracked<Traced>,
83	    sink: TrackedMut<Sink>,
84	    route: Tracked<Route>,
85	    children: &[Pair],
86	    locator: Tracked<Locator>,
87	    initial: StyleChain,
88	) -> SourceResult<Vec<LayoutedPage>> {
89	    let introspector = Protected::from_raw(introspector);
90	    let link = LocatorLink::new(locator);
91	    let mut locator = Locator::link(&link).split();
92	    let mut engine = Engine {
93	        library,
94	        world,
95	        introspector,
96	        traced,
97	        sink,
98	        route: Route::extend(route),
99	    };
100	
101	    // Determine the page-wide styles.
102	    let styles = Styles::root(children, initial);
103	    let styles = StyleChain::new(&styles);
104	
105	    // When one of the lengths is infinite the page fits its content along
106	    // that axis.
107	    let width = styles.resolve(PageElem::width).unwrap_or(Abs::inf());
108	    let height = styles.resolve(PageElem::height).unwrap_or(Abs::inf());
109	    let mut size = Size::new(width, height);
110	    if styles.get(PageElem::flipped) {
111	        std::mem::swap(&mut size.x, &mut size.y);
112	    }
113	
114	    let mut min = width.min(height);
115	    if !min.is_finite() {
116	        min = Paper::A4.width();
117	    }
118	
119	    // Determine the margins.
120	    let default = Rel::<Length>::from((2.5 / 21.0) * min);
121	    let margin = styles.get(PageElem::margin).unwrap_or_default();
122	    let margin_two_sided = margin.two_sided.unwrap_or(false);
123	    let margin = margin
124	        .sides
125	        .map(|side| side.and_then(Smart::custom).unwrap_or(default))
126	        .resolve(styles)
127	        .relative_to(size);
128	
129	    let bleed = styles.get(PageElem::bleed);
130	    let bleed_two_sided = bleed.two_sided.unwrap_or(false);
131	    let bleed = bleed
132	        .sides
133	        .map(|side| side.unwrap_or(Rel::zero()))
134	        .resolve(styles)
135	        .relative_to(size);
136	
137	    let fill = styles.get_cloned(PageElem::fill);
138	    let foreground = styles.get_ref(PageElem::foreground);
139	    let background = styles.get_ref(PageElem::background);
140	    let header_ascent = styles.resolve(PageElem::header_ascent).relative_to(margin.top);
141	    let footer_descent =
142	        styles.resolve(PageElem::footer_descent).relative_to(margin.bottom);
143	    let numbering = styles.get_ref(PageElem::numbering);
144	    let supplement = match styles.get_cloned(PageElem::supplement) {
145	        Smart::Auto => TextElem::packed(PageElem::local_name_in(styles)),
146	        Smart::Custom(content) => content.unwrap_or_default(),
147	    };
148	    let number_align = styles.get(PageElem::number_align);
149	    let binding = styles.get(PageElem::binding).unwrap_or_else(|| {
150	        match styles.resolve(TextElem::dir) {
151	            Dir::LTR => Binding::Left,
152	            _ => Binding::Right,
153	        }
154	    });
155	
156	    // Construct the numbering (for header or footer).
157	    let numbering_marginal = numbering.as_ref().map(|numbering| {
158	        let both = match numbering {
159	            Numbering::Pattern(pattern) => pattern.pieces() >= 2,
160	            Numbering::Func(_) => true,
161	        };
162	
163	        let mut counter = CounterDisplayElem::new(
164	            Counter::new(CounterKey::Page),
165	            Smart::Custom(numbering.clone()),
166	            both,
167	        )
168	        .pack();
169	
170	        // We interpret the Y alignment as selecting header or footer
171	        // and then ignore it for aligning the actual number.
172	        if let Some(x) = number_align.x() {
173	            counter = counter.aligned(x.into());
174	        }
175	
176	        counter
177	    });
178	
179	    let header = styles.get_ref(PageElem::header);
180	    let footer = styles.get_ref(PageElem::footer);
181	    let (header, footer) = if matches!(number_align.y(), Some(OuterVAlignment::Top)) {
182	        (header.as_ref().unwrap_or(&numbering_marginal), footer.as_ref().unwrap_or(&None))
183	    } else {
184	        (header.as_ref().unwrap_or(&None), footer.as_ref().unwrap_or(&numbering_marginal))
185	    };
186	
187	    // Layout the children.
188	    let area = size - margin.sum_by_axis();
189	    let fragment = layout_flow(
190	        &mut engine,
191	        children,
192	        &mut locator,
193	        styles,
194	        Regions::repeat(area, area.map(Abs::is_finite)),
195	        ColumnOptions {
196	            count: styles.get(PageElem::columns),
197	            balanced: styles.get(ColumnsElem::balanced),
198	            gutter: styles.get(ColumnsElem::gutter).resolve(styles),
199	            separator: styles.get_cloned(ColumnsElem::separator),
200	        },
201	        FlowMode::Root,
202	    )?;
203	
204	    // Layouts a single marginal.
205	    let mut layout_marginal = |content: &Option<Content>, area, align| {
206	        let Some(content) = content else { return Ok(None) };
207	        let aligned = content.clone().set(AlignElem::alignment, align);
208	        crate::layout_frame(
209	            &mut engine,
210	            &aligned,
211	            locator.next(&content.span()),
212	            styles,
213	            Region::new(area, Axes::splat(true)),
214	        )
215	        .map(Some)
216	    };
217	
218	    // Layout marginals.
219	    let mut layouted = Vec::with_capacity(fragment.len());
220	
221	    let header = header.clone().map(|h| h.artifact(ArtifactKind::Header));
222	    let footer = footer.clone().map(|f| f.artifact(ArtifactKind::Footer));
223	    let background = background.clone().map(|b| b.artifact(ArtifactKind::Background));
224	
225	    for inner in fragment {
226	        let header_size = Size::new(inner.width(), margin.top - header_ascent);
227	        let footer_size = Size::new(inner.width(), margin.bottom - footer_descent);
228	        let full_size = inner.size() + margin.sum_by_axis() + bleed.sum_by_axis();
229	        let mid = HAlignment::Center + VAlignment::Horizon;
230	        layouted.push(LayoutedPage {
231	            inner,
232	            fill: fill.clone(),
233	            numbering: numbering.clone(),
234	            supplement: supplement.clone(),
235	            header: layout_marginal(&header, header_size, Alignment::BOTTOM)?,
236	            footer: layout_marginal(&footer, footer_size, Alignment::TOP)?,
237	            background: layout_marginal(&background, full_size, mid)?,
238	            foreground: layout_marginal(foreground, full_size, mid)?,
239	            margin,
240	            margin_two_sided,
241	            bleed,
242	            bleed_two_sided,
243	            binding,
244	        });
245	    }
246	
247	    Ok(layouted)
248	}
