9	/// Piece together the inner page frame and the marginals. We can only do this
10	/// at the very end because inside/outside margins require knowledge of the
11	/// physical page number, which is unknown during parallel layout.
12	pub fn finalize(
13	    engine: &mut Engine,
14	    counter: &mut ManualPageCounter,
15	    tags: &mut Vec<Tag>,
16	    LayoutedPage {
17	        inner,
18	        mut margin,
19	        margin_two_sided,
20	        mut bleed,
21	        bleed_two_sided,
22	        binding,
23	        header,
24	        footer,
25	        background,
26	        foreground,
27	        fill,
28	        numbering,
29	        supplement,
30	    }: LayoutedPage,
31	) -> SourceResult<Page> {
32	    // If two sided, left becomes inside and right becomes outside.
33	    // Thus, for left-bound pages, we want to swap on even pages and
34	    // for right-bound pages, we want to swap on odd pages.
35	    let swap = binding.swap(counter.physical());
36	    if margin_two_sided && swap {
37	        std::mem::swap(&mut margin.left, &mut margin.right);
38	    }
39	    if bleed_two_sided && swap {
40	        std::mem::swap(&mut bleed.left, &mut bleed.right);
41	    }
42	
43	    // Create a frame for the full page.
44	    let mut frame = Frame::hard(inner.size() + margin.sum_by_axis());
45	
46	    // Add tags.
47	    for tag in tags.drain(..) {
48	        frame.push(Point::zero(), FrameItem::Tag(tag));
49	    }
50	
51	    let bleed_origin = Point::new(-bleed.left, -bleed.top);
52	
53	    // Add the "before" marginals. The order in which we push things here is
54	    // important as it affects the relative ordering of introspectable elements
55	    // and thus how counters resolve.
56	    if let Some(background) = background {
57	        frame.push_frame(bleed_origin, background);
58	    }
59	    if let Some(header) = header {
60	        frame.push_frame(Point::with_x(margin.left), header);
61	    }
62	
63	    // Add the inner contents.
64	    frame.push_frame(Point::new(margin.left, margin.top), inner);
65	
66	    // Add the "after" marginals.
67	    if let Some(footer) = footer {
68	        let y = frame.height() - footer.height();
69	        frame.push_frame(Point::new(margin.left, y), footer);
70	    }
71	    if let Some(foreground) = foreground {
72	        frame.push_frame(bleed_origin, foreground);
73	    }
74	
75	    // Apply counter updates from within the page to the manual page counter.
76	    counter.visit(engine, &frame)?;
77	
78	    // Get this page's number and then bump the counter for the next page.
79	    let number = counter.logical();
80	    counter.step();
81	
82	    Ok(Page { frame, bleed, fill, numbering, supplement, number })
83	}
